-- Bilingual company search (additive): Hebrew name + aliases per company.
ALTER TABLE "Company" ADD COLUMN IF NOT EXISTS "nameHe" TEXT;
ALTER TABLE "Company" ADD COLUMN IF NOT EXISTS "aliases" TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE "Company" ADD COLUMN IF NOT EXISTS "aliasesSource" TEXT;

